cover("1221_s1","AR 101","Eligibility denials: 4 causes and fixes","The most preventable denial there is",1,n)
code("1221_s2","Inactive","Coverage ended or not yet active on the date of service","Verify eligibility for every visit, not just the first one.",2,n)
code("1221_s3","Wrong payer","The patient switched plans and the old card was billed","Ask at every check-in: has your insurance changed?",3,n)
code("1221_s4","ID mismatch","Name, date of birth or member ID doesn't match the payer","Copy details exactly from the card or the eligibility response.",4,n)
