cover("1223_s1","CODING 101","New patient or established?","One rule decides the E/M code",1,n)
bullets("1223_s2","The 3-year rule",["A patient is new if they haven't received professional services from the same physician, or another physician of the same specialty in the same group, in the past 3 years"],2,n)
bullets("1223_s3","Common mistakes",["Billing new because the patient is new to the location","Ignoring visits with a same-specialty colleague in the group","Not checking the 3-year history"],3,n)
bullets("1223_s4","Why it matters",["New patient codes pay more","Payers audit them closely","Wrong choice means denials or paybacks"],4,n)
cta("1223_s5","Check the history before you pick the code.","Follow @rcm.axis for more coding basics.",5,n)
cards("1224","CAREERS IN RCM","Soft skills that make great AR callers",[("Clear phone voice","Payer reps help people who are easy to follow."),("Sharp notes","Reference numbers, names, dates. Every call."),("Follow-through","The claim isn't done until it's paid.")],"Skills get you hired. Habits get you promoted.")
single("1225","SEASON'S GREETINGS","Merry Christmas from RCMAXIS.","Wishing you and your teams a peaceful holiday. Thank you to everyone keeping US healthcare running this season.",dark=True)
single("1226","YEAR-END TIP","Close the year clean.","Review AR over 90 days and any claims close to their filing limits before December 31. Old claims only get harder in January.")
single("1227","ABOUT RCMAXIS","2026: the year RCMAXIS began.","We started RCMAXIS to give US specialty practices a focused revenue cycle partner. Thank you for following the build.",dark=True)
