cover("1228_s1","RCM 101","5 RCM terms every beginner should know","Learn the language first",1,n)
code("1228_s2","Clearinghouse","The middleman between the practice and the payer","Checks claims for errors and routes them electronically.",2,n)
code("1228_s3","Payer","The insurer or program that pays the claim","Commercial plans, Medicare, Medicaid and others.",3,n)
code("1228_s4","Adjudication","The payer's review and decision on a claim","Ends in paid, partially paid or denied.",4,n)
code("1228_s5","Write-off","A balance the practice won't collect","Contractual write-offs are normal. Avoidable ones are lost revenue.",5,n)
code("1228_s6","Coinsurance","The patient's percentage share after the deductible","Example: the plan pays 80%, the patient pays 20%.",6,n)
cta("1228_s7","Which term confused you most when you started?","Tell us in the comments.\nFollow @rcm.axis",7,n)
cards("1229","PATIENT BALANCES","Deductible vs. copay vs. coinsurance",[("Deductible","What the patient pays before the plan starts sharing costs."),("Copay","A fixed amount per visit or service."),("Coinsurance","A percentage of the cost after the deductible.")],"Know which one applies before you bill the patient.")
